def text(en,mn,tag='span',cls='',extra=''):
    attrs=(' class="'+cls+'"') if cls else ''
    return '<'+tag+attrs+' data-en="'+escape(en,quote=True)+'" data-mn="'+escape(mn,quote=True)+'" '+extra+'>'+en+'</'+tag+'>'
def link(en,mn,href,cls='',extra=''):
    return text(en,mn,'a',cls,'href="'+href+'" '+extra)
